// Editable image-space articulated puppet; this is not automatic anatomy recovery.
export const cutoutWalkDefaults={walkFrontShoulderX:474,walkFrontShoulderY:287,walkFrontElbowX:491,walkFrontElbowY:523,walkFrontWristX:554,walkFrontWristY:720,walkBackShoulderX:618,walkBackShoulderY:458,walkBackElbowX:704,walkBackElbowY:595,walkBackWristX:766,walkBackWristY:625,walkArmSwing:7,walkFrontArmFactor:1.15,walkBackArmFactor:1,walkElbowSwing:4,walkWristSwing:2,walkArmsEnabled:true,walkRate:.85,walkStride:12,walkKnee:10,walkPhase:0,walkBob:3,walkEdgeThreshold:100,walkRig:{width:1024,height:1536,hip:[520,930],backKnee:[310,1160],frontKnee:[700,1170],flashlight:[850,690],parts:{body:[[0,0],[1024,0],[1024,960],[0,960]],backThigh:[[350,890],[550,940],[390,1195],[220,1160]],backShin:[[235,1120],[405,1160],[370,1475],[45,1475],[45,1320]],frontThigh:[[500,890],[740,900],[810,1200],[600,1210]],frontShin:[[600,1130],[805,1120],[860,1290],[980,1370],[965,1490],[620,1490]]}}};
const cache=new WeakMap();function parts(image,f){const key=JSON.stringify([f.walkRig,f.walkEdgeThreshold,f.walkArmsEnabled,image.src,image._assetRevision]),old=cache.get(image);if(old?.key===key)return old.parts;const rig=f.walkRig,result={};const cuts={...rig.parts};if(f.walkArmsEnabled){cuts.backArm=[[610,445],[670,490],[758,596],[875,630],[910,760],[810,780],[690,690],[610,590]];cuts.frontArm=[[436,245],[535,260],[560,460],[611,690],[627,811],[570,834],[518,775],[451,590],[410,410]];}for(const [name,poly]of Object.entries(cuts)){const canvas=Object.assign(document.createElement('canvas'),{width:rig.width,height:rig.height}),c=canvas.getContext('2d');c.beginPath();poly.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.clip();c.drawImage(image,0,0,rig.width,rig.height);const pixels=c.getImageData(0,0,rig.width,rig.height);for(let i=3;i<pixels.data.length;i+=4)if(pixels.data[i]<f.walkEdgeThreshold)pixels.data[i]=0;if(name.endsWith('Arm')){const W=rig.width,H=rig.height,seen=new Uint8Array(W*H),queue=new Int32Array(W*H);let largest=[];for(let k=0;k<W*H;k++){if(seen[k]||pixels.data[k*4+3]<f.walkEdgeThreshold)continue;let head=0,tail=1;queue[0]=k;seen[k]=1;while(head<tail){const n=queue[head++],x=n%W;for(const m of [x?n-1:-1,x<W-1?n+1:-1,n-W,n+W])if(m>=0&&m<W*H&&!seen[m]&&pixels.data[m*4+3]>=f.walkEdgeThreshold){seen[m]=1;queue[tail++]=m;}}if(tail>largest.length)largest=Array.from(queue.subarray(0,tail));}const keep=new Uint8Array(W*H);for(const k of largest)keep[k]=1;for(let k=0;k<W*H;k++)if(!keep[k])pixels.data[k*4+3]=0;}c.putImageData(pixels,0,0);result[name]=canvas}cache.set(image,{key,parts:result});return result;}
export function cutoutWalkPose(time,input={}){const f={...cutoutWalkDefaults,...input},p=time*f.walkRate*Math.PI*2+f.walkPhase;return {back:Math.sin(p)*f.walkStride,front:-Math.sin(p)*f.walkStride,backKnee:Math.max(0,Math.sin(p+.7))*f.walkKnee,frontKnee:Math.max(0,-Math.sin(p+.7))*f.walkKnee,arm:Math.sin(p)*f.walkArmSwing,elbow:Math.sin(p+.5)*f.walkElbowSwing,wrist:Math.sin(p+.8)*f.walkWristSwing,bob:Math.cos(p*2)*f.walkBob};}
export function deformWalkArm(p,name,pose,f){const front=name==='frontArm',shoulder=front?[f.walkFrontShoulderX,f.walkFrontShoulderY]:[f.walkBackShoulderX,f.walkBackShoulderY],elbow=front?[f.walkFrontElbowX,f.walkFrontElbowY]:[f.walkBackElbowX,f.walkBackElbowY],wrist=front?[f.walkFrontWristX,f.walkFrontWristY]:[f.walkBackWristX,f.walkBackWristY],sign=front?1:-1,clamp=x=>Math.max(0,Math.min(1,x)),blend=(a,b,q)=>[a[0]+(b[0]-a[0])*q,a[1]+(b[1]-a[1])*q],turn=(p,o,d)=>{const a=d*Math.PI/180,x=p[0]-o[0],y=p[1]-o[1];return[o[0]+x*Math.cos(a)-y*Math.sin(a),o[1]+x*Math.sin(a)+y*Math.cos(a)]};let q=blend(p,turn(p,wrist,sign*pose.wrist),clamp((p[1]-wrist[1]+20)/50));q=blend(q,turn(q,elbow,sign*pose.elbow),clamp((p[1]-elbow[1]+25)/70));return turn(q,shoulder,sign*pose.arm*(front?f.walkFrontArmFactor:f.walkBackArmFactor));}
function paintArmMesh(c,im,name,pose,f){const front=name==='frontArm',[x0,y0,x1,y1]=front?[400,240,640,840]:[600,440,915,790],nx=6,ny=12;const draw=(src,dst)=>{const [[x0,y0],[x1,y1],[x2,y2]]=src,[[u0,v0],[u1,v1],[u2,v2]]=dst,D=x0*(y1-y2)+x1*(y2-y0)+x2*(y0-y1);const A=(u0*(y1-y2)+u1*(y2-y0)+u2*(y0-y1))/D,B=(v0*(y1-y2)+v1*(y2-y0)+v2*(y0-y1))/D,C=(u0*(x2-x1)+u1*(x0-x2)+u2*(x1-x0))/D,E=(v0*(x2-x1)+v1*(x0-x2)+v2*(x1-x0))/D,F=(u0*(x1*y2-x2*y1)+u1*(x2*y0-x0*y2)+u2*(x0*y1-x1*y0))/D,G=(v0*(x1*y2-x2*y1)+v1*(x2*y0-x0*y2)+v2*(x0*y1-x1*y0))/D;c.save();c.beginPath();dst.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.clip();c.transform(A,B,C,E,F,G);c.drawImage(im,0,0);c.restore();};for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const xx=x0+(x1-x0)*x/nx,yy=y0+(y1-y0)*y/ny,dx=(x1-x0)/nx,dy=(y1-y0)/ny,src=[[xx,yy],[xx+dx,yy],[xx+dx,yy+dy],[xx,yy+dy]],dst=src.map(p=>deformWalkArm(p,name,pose,f));for(const ids of [[0,1,2],[0,2,3]])draw(ids.map(i=>src[i]),ids.map(i=>dst[i]));}}
export function paintCutoutWalk(c,image,time,rect,input={}){if(!(image?.naturalWidth||image?.width))return false;const f={...cutoutWalkDefaults,...input},rig=f.walkRig,ps=parts(image,f),pose=cutoutWalkPose(time,f),[x,y,w,h]=rect;c.save();c.translate(x,y+pose.bob*h/rig.height);c.scale(w/rig.width,h/rig.height);const hip=rig.hip,draw=(name,origin)=>c.drawImage(ps[name],-origin[0],-origin[1]);for(const side of ['back','front']){c.save();c.translate(...hip);c.rotate(pose[side]*Math.PI/180);draw(side+'Thigh',hip);const knee=rig[side+'Knee'];c.translate(knee[0]-hip[0],knee[1]-hip[1]);c.rotate(pose[side+'Knee']*Math.PI/180);draw(side+'Shin',knee);c.restore();}if(f.walkArmsEnabled){ // redraw the body without the original arm pixels, then articulate original artwork.
 const body=ps.body,bc=body.getContext('2d');if(!body._armsRemoved){bc.save();bc.globalCompositeOperation='destination-out';for(const poly of [[[436,245],[535,260],[560,460],[611,690],[627,811],[570,834],[518,775],[451,590],[410,410]],[[610,445],[670,490],[758,596],[875,630],[910,760],[810,780],[690,690],[610,590]]]){bc.beginPath();poly.forEach((p,i)=>i?bc.lineTo(...p):bc.moveTo(...p));bc.closePath();bc.fill();}bc.restore();body._armsRemoved=true;}
 c.save();c.beginPath();c.moveTo(430,280);c.lineTo(530,280);c.lineTo(610,840);c.lineTo(490,840);c.lineTo(405,420);c.closePath();c.clip();c.drawImage(image,330,390,100,510,425,280,180,560);c.restore();c.drawImage(ps.body,0,0);
 // Clear original arms using the cached cut body on subsequent frames; first draw below is covered by arm layers.
 paintArmMesh(c,ps.backArm,'backArm',pose,f);paintArmMesh(c,ps.frontArm,'frontArm',pose,f);
}else c.drawImage(ps.body,0,0);c.restore();const tip=f.walkArmsEnabled?deformWalkArm(rig.flashlight,'backArm',pose,f):rig.flashlight;return {flashlight:[x+tip[0]/rig.width*w,y+(tip[1]+pose.bob)/rig.height*h],pose};}
